data.query:
query Query($where: InventoryWhereInput) {
  inventory(where: $where) {
    edges {
      node {
        id
				active
        barcode
        number
        inventoryStatus {
          id
          name
          active
          suspect
          containment
          productionLoaded
          movePrevent
        }
        masterInventory {
          id
          number
          masterInventoryStatus {
            id
            name
            active
            containment

          }
        }
      }
    }
  }
}

